// Брендовая база, часть 11: молоко и кисломолочка, йогурты, творожки,
// сыры, колбасы/сосиски/ветчина, соки и напитки — расширение по просьбе
// Кати 28.11 («молоко, йогурты, соки, сыры, колбасы»).
//
// КФЖУ — на 100 г / 100 мл; значения типовые по виду и жирности
// (молочные продукты стандартизованы жирностью), ккал считаются из
// Б/Ж/У по уравнению Атуотера (4Б + 9Ж + 4У, клетчатка 2) прямо в
// фабрике f() — база сходится с энергетическим балансом.
// al — короткие алиасы для поиска (голос/текст и «по составу»).

const f = (id, emoji, name, p, f_, c, fib, sug, dg, tags, al) => ({
  id,
  emoji,
  name,
  kcal: Math.round(p * 4 + f_ * 9 + (c - fib) * 4 + fib * 2),
  p,
  f: f_,
  c,
  fib,
  sug,
  defaultGrams: dg,
  tags,
  al,
})

